import{_ as t,o as a,c as l,a2 as o}from"./chunks/framework.ClgMjOt7.js";const g=JSON.parse('{"title":"検索機能 & ウォッチリスト仕様","description":"タグ検索、各種フィルター、ソート、お気に入りタグ管理（ウォッチリスト）","frontmatter":{"title":"検索機能 & ウォッチリスト仕様","description":"タグ検索、各種フィルター、ソート、お気に入りタグ管理（ウォッチリスト）"},"headers":[],"relativePath":"features/search.md","filePath":"features/search.md","lastUpdated":1786168778000}'),r={name:"features/search.md"};function i(s,e,d,c,n,h){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="検索機能-ウォッチリスト仕様" tabindex="-1">検索機能 &amp; ウォッチリスト仕様 <a class="header-anchor" href="#検索機能-ウォッチリスト仕様" aria-label="Permalink to &quot;検索機能 &amp; ウォッチリスト仕様&quot;">​</a></h1><p>検索画面 (<code>SearchScreen</code>) では、複雑な検索クエリの構築とフィルタリング、およびウォッチリスト管理機能を提供します。</p><hr><h2 id="検索モード-searchtarget" tabindex="-1">検索モード (<code>SearchTarget</code>) <a class="header-anchor" href="#検索モード-searchtarget" aria-label="Permalink to &quot;検索モード (`SearchTarget`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">識別子</th><th style="text-align:left;">UI 表示名</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>PartialTags</code></td><td style="text-align:left;"><strong>タグ部分一致</strong></td><td style="text-align:left;">入力したタグを一部に含む作品を検索</td></tr><tr><td style="text-align:left;"><code>ExactTag</code></td><td style="text-align:left;"><strong>タグ完全一致</strong></td><td style="text-align:left;">指定したタグが完全一致する作品のみを検索</td></tr><tr><td style="text-align:left;"><code>TitleAndCaption</code></td><td style="text-align:left;"><strong>タイトル・キャプション</strong></td><td style="text-align:left;">作品のタイトルおよび説明文本文を対象にしたテキスト検索</td></tr><tr><td style="text-align:left;"><code>Users</code></td><td style="text-align:left;"><strong>ユーザー検索</strong></td><td style="text-align:left;">クリエイターの表示名または Pixiv ID によるユーザー検索</td></tr></tbody></table><hr><h2 id="検索フィルター-ソート設定" tabindex="-1">検索フィルター &amp; ソート設定 <a class="header-anchor" href="#検索フィルター-ソート設定" aria-label="Permalink to &quot;検索フィルター &amp; ソート設定&quot;">​</a></h2><h3 id="_1-ソート順-searchsort" tabindex="-1">1. ソート順 (<code>SearchSort</code>) <a class="header-anchor" href="#_1-ソート順-searchsort" aria-label="Permalink to &quot;1. ソート順 (`SearchSort`)&quot;">​</a></h3><ul><li><code>DateDesc</code>: 投稿日時が新しい順 (降順)</li><li><code>DateAsc</code>: 投稿日時が古い順 (昇順)</li><li><code>PopularDesc</code>: 人気順 (Pixiv Premium または条件適合時)</li></ul><h3 id="_2-検索対象期間-searchduration" tabindex="-1">2. 検索対象期間 (<code>SearchDuration</code>) <a class="header-anchor" href="#_2-検索対象期間-searchduration" aria-label="Permalink to &quot;2. 検索対象期間 (`SearchDuration`)&quot;">​</a></h3><ul><li><code>All</code>: 全期間</li><li><code>WithinDay</code>: 24時間以内</li><li><code>WithinWeek</code>: 1週間以内</li><li><code>WithinMonth</code>: 1ヶ月以内</li></ul><h3 id="_3-ブックマーク数フィルター-searchbookmarkfilter" tabindex="-1">3. ブックマーク数フィルター (<code>SearchBookmarkFilter</code>) <a class="header-anchor" href="#_3-ブックマーク数フィルター-searchbookmarkfilter" aria-label="Permalink to &quot;3. ブックマーク数フィルター (`SearchBookmarkFilter`)&quot;">​</a></h3><p>評価数タグ（〇〇users入り）に適合する作品のみに絞り込みます。</p><ul><li><code>None</code>: 指定なし</li><li><code>Bookmark100</code>: 100users入り 以上</li><li><code>Bookmark500</code>: 500users入り 以上</li><li><code>Bookmark1000</code>: 1000users入り 以上</li><li><code>Bookmark5000</code>: 5000users入り 以上</li><li><code>Bookmark10000</code>: 10000users入り 以上</li></ul><h3 id="_4-コンテンツ・年齢制限-allowr18" tabindex="-1">4. コンテンツ・年齢制限 (<code>allowR18</code>) <a class="header-anchor" href="#_4-コンテンツ・年齢制限-allowr18" aria-label="Permalink to &quot;4. コンテンツ・年齢制限 (`allowR18`)&quot;">​</a></h3><ul><li>全年齢対象 / R-18 / R-18G 作品の表示切り替え。</li></ul><hr><h2 id="ウォッチリスト-favoritetagsscreen-watchliststore" tabindex="-1">ウォッチリスト (<code>FavoriteTagsScreen</code> / <code>WatchlistStore</code>) <a class="header-anchor" href="#ウォッチリスト-favoritetagsscreen-watchliststore" aria-label="Permalink to &quot;ウォッチリスト (`FavoriteTagsScreen` / `WatchlistStore`)&quot;">​</a></h2><p>頻繁にアクセスするタグを「ウォッチリスト（お気に入りタグ）」としてローカル登録できます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> [ 検索結果画面 ] ──( 「★ ウォッチリストに追加」 )──&gt; Room DB (FavoriteTagEntity)</span></span>\n<span class="line"><span>                                                            │</span></span>\n<span class="line"><span> [ FavoriteTagsScreen ] &lt;──( 未読件数チェック API 呼び出し )─┘</span></span></code></pre></div><ul><li><strong>データベース構成 (<code>FavoriteTagEntity</code>)</strong>: <ul><li><code>name</code>: タグ名 (PK)</li><li><code>translatedName</code>: 翻訳タグ名</li><li><code>addedAt</code>: 追加日時タイムスタンプ</li><li><code>lastCheckedAt</code>: 最終確認日時</li></ul></li><li><strong>新着更新チェック</strong>: 各タグの最新作品IDを比較し、新着投稿がある場合に未読バッジを表示。</li><li><strong>クイック検索</strong>: タグをタップすることで、設定済みのフィルター条件を適用した検索結果を即座に開きます。</li></ul>',21)])])}const p=t(r,[["render",i]]);export{g as __pageData,p as default};
